'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const signs=[
 {id:'G-01',floor:0,x:400,y:398,type:'Directory',text:'Welcome to North',arrow:'↑',location:'Main entrance',size:'600 × 800',material:'Printed aluminium panel',revision:1,status:'Concept'},
 {id:'G-02',floor:0,x:400,y:255,type:'Directional',text:'First floor · Lift',arrow:'→',location:'Central junction',size:'600 × 200',material:'Printed aluminium panel',revision:1,status:'Concept'},
 {id:'G-03',floor:0,x:210,y:330,type:'Identification',text:'Reception',arrow:'←',location:'Reception entrance',size:'300 × 150',material:'Printed aluminium panel',revision:1,status:'Concept'},
 {id:'G-04',floor:0,x:210,y:190,type:'Identification',text:'Design studio',arrow:'←',location:'Studio entrance',size:'300 × 150',material:'Printed aluminium panel',revision:1,status:'Concept'},
 {id:'G-05',floor:0,x:650,y:330,type:'Identification',text:'Toilets',arrow:'→',location:'Toilet entrance',size:'300 × 150',material:'Printed aluminium panel',revision:1,status:'Concept'},
 {id:'F-01',floor:1,x:565,y:255,type:'Directional',text:'Seminar room 2.03',arrow:'←',location:'Lift lobby',size:'600 × 200',material:'Printed aluminium panel',revision:1,status:'Concept'},
 {id:'F-02',floor:1,x:210,y:190,type:'Identification',text:'Seminar room 2.03',arrow:'←',location:'Seminar room entrance',size:'300 × 150',material:'Printed aluminium panel',revision:1,status:'Concept'},
 {id:'F-03',floor:1,x:210,y:330,type:'Identification',text:'Meeting room',arrow:'←',location:'Meeting room entrance',size:'300 × 150',material:'Printed aluminium panel',revision:1,status:'Concept'},
 {id:'F-04',floor:1,x:650,y:330,type:'Identification',text:'Library',arrow:'→',location:'Library entrance',size:'300 × 150',material:'Printed aluminium panel',revision:1,status:'Concept'}
];
const destinations={reception:{floor:0,sign:'G-03',path:'400,440 400,255 210,255 210,330',description:'Enter, turn left at the central corridor, then find Reception.'},studio:{floor:0,sign:'G-04',path:'400,440 400,255 210,255 210,190',description:'Enter, turn left at the central corridor, then find the Design studio.'},wc:{floor:0,sign:'G-05',path:'400,440 400,255 650,255 650,330',description:'Enter, turn right along the central corridor, then find Toilets.'},seminar:{floor:1,sign:'F-02',path:'565,180 565,255 210,255 210,190',description:'On the ground floor, follow the corridor to the lift. On floor 01, turn left and follow signs to Seminar room 2.03.'},meeting:{floor:1,sign:'F-03',path:'565,180 565,255 210,255 210,330',description:'Take the lift to floor 01. Turn left along the corridor, then find the Meeting room.'},library:{floor:1,sign:'F-04',path:'565,180 565,255 650,255 650,330',description:'Take the lift to floor 01. Turn right along the corridor, then find the Library.'}};
let floor=0,selected='G-02',tourStep=-1;
function current(){return signs.find(s=>s.id===selected)}
function setFloor(value){floor=Number(value);if(current().floor!==floor)selected=signs.find(s=>s.floor===floor).id;render()}
function choose(id){selected=id;floor=current().floor;render()}
function room(x,y,w,h,label,sub){return `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#fff" stroke="#a9b7c5" stroke-width="3"/><text x="${x+w/2}" y="${y+h/2-4}" text-anchor="middle" fill="#253b51" font-size="17" font-weight="600">${label}</text><text x="${x+w/2}" y="${y+h/2+20}" text-anchor="middle" fill="#657687" font-size="12">${sub}</text>`}
function renderMap(){
 const d=destinations[$('#destination').value];
 let route=d?(floor===0?(d.floor===0?d.path:'400,440 400,255 565,255 565,180'):(d.floor===1?d.path:'')):'';
 $('#floor-label').textContent=floor?'FIRST FLOOR / 01':'GROUND FLOOR / 00';
 $('#plan').innerHTML=`<title>${floor?'First':'Ground'} floor schematic; numbered circles select signs</title><defs><pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#d7dee5"/></pattern></defs><rect width="800" height="490" fill="url(#grid)"/><path d="M60 60H740V400H430V440H370V400H60Z" fill="#e6ecf1" stroke="#7b8b9b" stroke-width="3"/>${room(60,60,290,135,floor?'Seminar room 2.03':'Design studio',floor?'LEARN / 01':'CREATE / 00')}${room(60,325,290,75,floor?'Meeting room':'Reception',floor?'MEET / 01':'ARRIVE / 00')}${room(490,60,150,135,'Lift','00 ↕ 01')}${room(640,60,100,135,'Stairs','00 ↕ 01')}${room(490,325,250,75,floor?'Library':'Toilets',floor?'READ / 01':'FACILITIES / 00')}<path d="M190 195H230 M190 325H230 M545 195H585 M630 325H670" stroke="#e6ecf1" stroke-width="8"/><text x="400" y="290" text-anchor="middle" font-size="12" fill="#657687">CENTRAL CORRIDOR</text><text x="400" y="469" text-anchor="middle" font-size="13" fill="#253b51">${floor?'FLOOR 01':'↑ MAIN ENTRANCE'}</text>${route?`<polyline class="route-line" points="${route}" fill="none" stroke="#2546cc" stroke-width="5" stroke-linejoin="round"/><circle cx="${route.split(' ').at(-1).split(',')[0]}" cy="${route.split(' ').at(-1).split(',')[1]}" r="9" fill="#2546cc" stroke="white" stroke-width="3"/>`:''}${signs.filter(s=>s.floor===floor).map(s=>`<g class="map-sign" role="button" tabindex="0" aria-label="Select ${s.id}: ${esc(s.text)}" data-sign="${s.id}"><circle cx="${s.x}" cy="${s.y}" r="${s.id===selected?21:17}" fill="${s.id===selected?'#142638':'#efef65'}" stroke="#142638" stroke-width="2"/><text x="${s.x}" y="${s.y+5}" text-anchor="middle" font-size="13" font-weight="700" fill="${s.id===selected?'#fff':'#142638'}">${s.id.slice(-2)}</text></g>`).join('')}`;
 $('#route-note').textContent=d?d.description+(floor===0&&d.floor===1?' Switch to First floor to continue the route.':floor===1&&d.floor===0?' This destination is on the ground floor.':''):'Choose a destination to trace a visitor’s journey from the main entrance.';
 $('#plan').querySelectorAll('[data-sign]').forEach(el=>{el.onclick=()=>choose(el.dataset.sign);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(el.dataset.sign)}}});
}
function signSVG(s){const directory=s.type==='Directory',h=directory?400:s.type==='Identification'?200:200;return `<svg xmlns="http://www.w3.org/2000/svg" width="${directory?600:s.type==='Identification'?300:600}mm" height="${directory?800:s.type==='Identification'?150:200}mm" viewBox="0 0 600 ${h}" role="img" aria-label="${esc(s.text)}"><rect width="600" height="${h}" fill="${s.type==='Identification'?'#efef65':'#142638'}"/><g font-family="Arial,sans-serif" fill="${s.type==='Identification'?'#142638':'white'}"><text x="28" y="38" font-size="15" letter-spacing="2">NORTH / ${s.floor?'FIRST FLOOR':'GROUND FLOOR'}</text>${s.type==='Directional'?`<text x="30" y="130" font-size="80" fill="#efef65">${s.arrow}</text>`:''}<text x="${s.type==='Directional'?120:28}" y="${directory?110:112}" font-size="${s.text.length>25?23:30}" font-weight="700">${esc(s.text)}</text>${directory?'<path d="M28 150H570 M28 250H570" stroke="#687986"/><text x="28" y="190" font-size="22">00 — Reception / Studio / Toilets</text><text x="28" y="290" font-size="22">01 — Seminar / Meeting / Library</text><text x="28" y="350" font-size="17" fill="#efef65">First floor via lift or stairs →</text>':''}</g></svg>`}
function renderInspector(){const s=current();$('#sign-id').textContent=s.id;$('#sign-title').textContent=s.type;$('#sign-preview').innerHTML=signSVG(s);$('#sign-text').value=s.text;$('#direction').value=s.arrow;$('#direction').disabled=s.type!=='Directional';$('#status').value=s.status;$('#specs').innerHTML=`<dt>Location</dt><dd>${esc(s.location)}</dd><dt>Proposed size</dt><dd>${s.size} mm</dd><dt>Proposed material</dt><dd>${s.material}</dd><dt>Revision</dt><dd>R${String(s.revision).padStart(2,'0')}</dd>`}
function renderRegister(){let filter=$('#filter').value;$('#register').innerHTML=signs.filter(s=>filter==='all'||s.floor===Number(filter)).map(s=>`<tr class="${s.id===selected?'selected-row':''}"><td><button data-row="${s.id}" aria-label="Inspect sign ${s.id}">${s.id} ↗</button></td><td>${s.floor?'01':'00'} / ${s.location}</td><td>${esc(s.text)}<small>${s.type}</small></td><td>${s.size}</td><td><span class="badge">${s.status}</span></td><td>R${String(s.revision).padStart(2,'0')}</td></tr>`).join('');document.querySelectorAll('[data-row]').forEach(b=>b.onclick=()=>{choose(b.dataset.row);$('.inspector').scrollIntoView({behavior:'smooth',block:'center'})})}
function render(){document.querySelectorAll('[data-floor]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.floor)===floor)));renderMap();renderInspector();renderRegister()}
document.querySelectorAll('[data-floor]').forEach(b=>b.onclick=()=>setFloor(b.dataset.floor));
$('#destination').onchange=()=>{const d=destinations[$('#destination').value];if(d){floor=d.floor;selected=d.sign}render()};
$('#sign-text').oninput=()=>{const s=current();s.text=$('#sign-text').value;$('#sign-preview').innerHTML=signSVG(s);renderRegister();renderMap()};
$('#sign-text').onchange=()=>{if(!current().text.trim())current().text='Untitled sign';current().revision++;renderInspector();renderRegister()};
$('#direction').onchange=()=>{current().arrow=$('#direction').value;current().revision++;renderInspector();renderRegister()};
$('#status').onchange=()=>{current().status=$('#status').value;current().revision++;renderInspector();renderRegister()};
$('#filter').onchange=renderRegister;
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#svg-export').onclick=()=>{download(`${current().id}-concept.svg`,signSVG(current()),'image/svg+xml');$('#feedback').textContent='SVG downloaded. Concept artwork requires production review.'};
const csvCell=v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';
$('#csv').onclick=()=>{const rows=[['ID','Floor','Location','Type','Text','Direction','Proposed size mm','Proposed material','Status','Revision'],...signs.map(s=>[s.id,s.floor,s.location,s.type,s.text,s.type==='Directional'?s.arrow:'',s.size,s.material,s.status,s.revision])];download('north-sign-register.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')};
$('#print').onclick=()=>window.print();
const steps=[{text:'1 / 4 — Arrival. The entrance directory introduces both floors and the destinations ahead.',floor:0,sign:'G-01'},{text:'2 / 4 — Decision. A visitor heading upstairs follows the junction sign to the lift.',floor:0,sign:'G-02'},{text:'3 / 4 — Confirmation. On the first floor, the directional sign continues the route to Seminar room 2.03.',floor:1,sign:'F-01'},{text:'4 / 4 — Destination. Select a sign, edit its text and see the same entry update in the register. Changes are local to this visit.',floor:1,sign:'F-02'}];
function showStep(){const s=steps[tourStep];$('#tour-note').hidden=false;$('#tour-text').textContent=s.text;$('#tour-next').textContent=tourStep===3?'Finish tour ✓':'Next step →';$('#destination').value='seminar';floor=s.floor;selected=s.sign;render()}
$('#tour').onclick=()=>{tourStep=0;showStep()};$('#tour-next').onclick=()=>{if(tourStep===3){$('#tour-note').hidden=true;tourStep=-1}else{tourStep++;showStep()}};$('#tour-close').onclick=()=>{$('#tour-note').hidden=true;tourStep=-1};render();
